#!/usr/bin/env bash
# =============================================================================
#  DeepSeek Harness relaunch helper (GENERATED by @local/dsh-wrainrock-daemon)
#
#  Used by the plugin's "重启" action. The action has to hand the port over
#  before it can be reclaimed, so this helper is spawned detached and then:
#
#    systemd       waits for <pid> (the old Harness) to exit, then restarts the
#                  unit through `systemctl --user`
#    systemd-kill  <pid> is the *supervisor*: stops it and every other
#                  supervisor of this install, waits for the port to free, then
#                  starts the unit. Needed when two systemd user managers each
#                  run the unit: a plain restart reaches only one of them and
#                  looks like a no-op ("it never restarts").
#    exec          waits for <pid>, then re-executes the captured command line
#                  (autostart is disabled)
#
#  usage: relaunch.sh <pid> <systemd|systemd-kill|exec> <unit> <cwd> [command...]
# =============================================================================
set -uo pipefail

OLD_PID="${1:-0}"
MODE="${2:-exec}"
UNIT="${3:-}"
CWD="${4:-}"
shift 4 2>/dev/null || true

PORT="${DSH_RESTART_PORT:-0}"
RUNTIME="${XDG_RUNTIME_DIR:-/run/user/$(id -u)}"
export XDG_RUNTIME_DIR="$RUNTIME"
# A unit started by the *other* user manager may not have the session bus in its
# environment; the manager socket lives at a fixed place on this host.
if [ -z "${DBUS_SESSION_BUS_ADDRESS:-}" ] && [ -S "$RUNTIME/bus" ]; then
  export DBUS_SESSION_BUS_ADDRESS="unix:path=$RUNTIME/bus"
fi

wait_gone() { # pid seconds
  # A zombie still answers kill -0, so look at /proc/PID/stat state instead: a
  # dead process either leaves /proc or is reported as 'Z'.
  local pid="$1" deadline=$(( $(date +%s) + $2 )) st
  while [ "$(date +%s)" -lt "$deadline" ]; do
    st="$(awk '{print $3}' "/proc/$pid/stat" 2>/dev/null)" || st=''
    case "$st" in ''|Z) return 0 ;; esac
    sleep 0.1
  done
  return 1
}

port_free() {
  [ "${PORT:-0}" -gt 0 ] 2>/dev/null || return 0
  command -v ss >/dev/null 2>&1 || return 0
  ss -ltnH "sport = :$PORT" 2>/dev/null | grep -q . && return 1
  return 0
}

# The supervisor script the unit runs. This helper is installed next to it
# (bin/relaunch.sh, bin/supervisor.sh), so the sibling path is authoritative —
# parsing systemd's `ExecStart` display breaks as soon as the path contains a
# space (`.../deepseek harness/...`), which is exactly the 2026-10-31 incident.
# The systemd query stays as a fallback for a helper that was copied elsewhere.
supervisor_script() {
  local sibling
  sibling="$(dirname -- "${BASH_SOURCE[0]:-$0}")/supervisor.sh"
  if [ -f "$sibling" ]; then
    printf '%s\n' "$sibling"
    return 0
  fi
  systemctl --user show "$UNIT" -p ExecStart --value 2>/dev/null \
    | sed -n 's/.*argv\[\]=\([^;]*\).*/\1/p' \
    | sed -e 's/^[^ ]* //' -e 's/^"//' -e 's/"$//'
}

stop_supervisors() { # script
  local script="$1" entry pid cmd n=0
  [ -n "$script" ] || return 0
  for entry in /proc/[0-9]*; do
    pid="${entry#/proc/}"
    [ -r "$entry/cmdline" ] || continue
    cmd="$(tr '\0' '\n' <"$entry/cmdline" 2>/dev/null | sed -n '2p')" || continue
    if [ "$cmd" = "$script" ]; then
      kill -TERM "$pid" 2>/dev/null && n=$((n + 1)) || true
    fi
  done
  if [ "$n" -gt 0 ]; then
    printf '[relaunch] stopped %s supervisor(s) of %s\n' "$n" "$script" >&2
  fi
  return 0
}

case "$MODE" in
  systemd-kill)
    [ -n "$UNIT" ] || exit 1
    sleep 0.2                      # let the HTTP 202 reach the page first
    stop_supervisors "$(supervisor_script)"
    if [ "${OLD_PID:-0}" -gt 1 ]; then
      kill -TERM "$OLD_PID" 2>/dev/null || true
      wait_gone "$OLD_PID" 20 || kill -KILL "$OLD_PID" 2>/dev/null || true
    fi
    for _ in $(seq 1 100); do port_free && break; sleep 0.2; done
    systemctl --user stop "$UNIT" >/dev/null 2>&1 || true
    if systemctl --user start "$UNIT" >/dev/null 2>&1; then exit 0; fi
    if systemctl --user restart "$UNIT" >/dev/null 2>&1; then exit 0; fi
    if busctl --user call org.freedesktop.systemd1 /org/freedesktop/systemd1 \
      org.freedesktop.systemd1.Manager StartUnit ss "$UNIT" replace >/dev/null 2>&1; then
      exit 0
    fi
    exit 1
    ;;
  systemd)
    # Wait up to 30s for the old Harness process to release the port.
    for _ in $(seq 1 300); do
      [ "$OLD_PID" -gt 1 ] || break
      kill -0 "$OLD_PID" 2>/dev/null || break
      sleep 0.1
    done
    sleep 0.6
    if systemctl --user restart "$UNIT" >/dev/null 2>&1; then
      exit 0
    fi
    # `systemctl --user` can be unavailable in restricted/namespaced sessions;
    # fall back to the same D-Bus call systemd exposes.
    if busctl --user call org.freedesktop.systemd1 /org/freedesktop/systemd1 \
      org.freedesktop.systemd1.Manager RestartUnit ss "$UNIT" replace >/dev/null 2>&1; then
      exit 0
    fi
    exit 1
    ;;
esac

# mode=exec: wait for the old process, then re-execute the captured command.
for _ in $(seq 1 300); do
  [ "$OLD_PID" -gt 1 ] || break
  kill -0 "$OLD_PID" 2>/dev/null || break
  sleep 0.1
done
sleep 0.6

[ -n "$CWD" ] && cd "$CWD" 2>/dev/null
if [ "$#" -eq 0 ]; then
  exit 1
fi
exec "$@"
